listEvents({ ruleId = null, deviceId = null, event = null, source = null, occurredAfter = null, occurredBefore = null, afterSequence = null, limit = null } = {}) {
  const clauses = [];
  const parameters = [];
  if (ruleId !== null) {
    clauses.push("rule_id = ?");
    parameters.push(ruleId);
  }
  if (deviceId !== null) {
    clauses.push("device_id = ?");
    parameters.push(deviceId);
  }
  if (event !== null) {
    clauses.push("event = ?");
    parameters.push(event);
  }
  if (source !== null) {
    clauses.push("source = ?");
    parameters.push(source);
  }
  if (occurredAfter !== null) {
    // occurred_at is RFC3339 UTC; dropping the trailing Z yields the format
    // julianday() reads, so the boundary is exact rather than lexical.
    clauses.push("julianday(substr(occurred_at, 1, length(occurred_at) - 1)) >= julianday(?)");
    parameters.push(occurredAfter.withoutZ);
  }
  if (occurredBefore !== null) {
    clauses.push("julianday(substr(occurred_at, 1, length(occurred_at) - 1)) < julianday(?)");
    parameters.push(occurredBefore.withoutZ);
  }
  if (afterSequence !== null) {
    clauses.push("sequence > ?");
    parameters.push(afterSequence);
  }
  const where = clauses.length > 0 ? ` WHERE ${clauses.join(" AND ")}` : "";
  const cap = limit === null ? "" : " LIMIT ?";
  if (limit !== null) {
    parameters.push(limit);
  }
  return this.database
    .prepare(`SELECT * FROM events${where} ORDER BY sequence${cap}`)
    .all(...parameters)

